            // 기초자산 기준
            arr[0] = "68955B";
        }
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        // arr[4]; //ctnt
        arr[5] = $c.lc.fn_GetAddTitle(dts_Mst.getCellData(dts_Mst.getRowPosition(), "COM_NM")); // add  title

        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DELIST_RSN_NM", cmb_Rsn_Cd.getText());
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ULY_DELIST_RSN_NM", cmb_Rsn_Uly_Cd.getText());
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 740 + 5;
    const hgt = 790 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

